package app.zhijian.notes;
import app.zhijian.notes.backup.ArchiveCodec;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
import java.io.*;import java.nio.file.*;import java.util.zip.*;
public class ArchiveTest {
 private JSONObject manifest() throws Exception{return new JSONObject().put("format","paper-notes").put("version",1).put("notes",new JSONArray()).put("todos",new JSONArray()).put("folders",new JSONArray()).put("media",new JSONObject());}
 @Test public void archiveRoundTripPreservesMedia() throws Exception {File media=Files.createTempDirectory("paper-media").toFile();Files.write(new File(media,"abc.png").toPath(),new byte[]{1,2,3});JSONObject m=manifest();m.getJSONObject("media").put("abc.png",ArchiveCodec.hash(new File(media,"abc.png")));ByteArrayOutputStream out=new ByteArrayOutputStream();ArchiveCodec.write(out,m,media);File stage=Files.createTempDirectory("paper-stage").toFile();JSONObject read=ArchiveCodec.read(new ByteArrayInputStream(out.toByteArray()),stage);assertEquals("paper-notes",read.getString("format"));assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(new File(stage,"media/abc.png").toPath()));}
 @Test public void missingMediaAndMalformedArchivesAreRejected() throws Exception {JSONObject m=manifest();m.getJSONObject("media").put("missing.png","hash");ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){z.putNextEntry(new ZipEntry("manifest.json"));z.write(m.toString().getBytes("UTF-8"));z.closeEntry();}try{ArchiveCodec.read(new ByteArrayInputStream(b.toByteArray()),Files.createTempDirectory("bad-paper").toFile());fail();}catch(IOException|IllegalArgumentException expected){}}
 @Test public void zipTraversalCannotWriteOutsideStage() throws Exception {ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){z.putNextEntry(new ZipEntry("../evil"));z.write(1);}File stage=Files.createTempDirectory("paper-safe").toFile();try{ArchiveCodec.read(new ByteArrayInputStream(b.toByteArray()),stage);fail();}catch(IllegalArgumentException|IOException expected){}assertFalse(new File(stage.getParentFile(),"evil").exists());}
 @Test public void markdownExportUsesUniqueNamesAndRelativeImages() throws Exception {File media=Files.createTempDirectory("paper-exp").toFile();Files.write(new File(media,"abc.png").toPath(),new byte[]{1});JSONArray notes=new JSONArray();notes.put(new JSONObject().put("id","a").put("title","../同名").put("markdown","![](media/abc.png)"));notes.put(new JSONObject().put("id","b").put("title","../同名").put("markdown","文本"));ByteArrayOutputStream b=new ByteArrayOutputStream();ArchiveCodec.writeMarkdown(b,notes,media);java.util.Map<String,String> files=new java.util.HashMap<>();try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(b.toByteArray()))){ZipEntry e;while((e=z.getNextEntry())!=null)files.put(e.getName(),new String(z.readAllBytes(),"UTF-8"));}assertTrue(files.containsKey("a.md"));assertTrue(files.containsKey("b.md"));assertTrue(files.get("a.md").contains("](media/abc.png)"));assertTrue(files.containsKey("media/abc.png"));}
 @Test public void attachmentReferencesIncludeMarkdownAndRichImages() {assertEquals(java.util.Collections.singleton("a.png"),ArchiveCodec.references("![图](media/a.png)","markdown"));assertEquals(java.util.Collections.singleton("b.jpg"),ArchiveCodec.references("<img src=\"media/b.jpg\">","rich"));}
 @Test public void oversizedBackupCannotBeReportedAsSuccessful() throws Exception {File media=Files.createTempDirectory("paper-limit").toFile();File image=new File(media,"big.png");try(RandomAccessFile f=new RandomAccessFile(image,"rw")){f.setLength(21L*1024*1024);}JSONObject m=manifest();m.getJSONObject("media").put("big.png",ArchiveCodec.hash(image));try{ArchiveCodec.write(new ByteArrayOutputStream(),m,media);fail("An unreadable backup was emitted");}catch(IllegalArgumentException expected){}}
 @Test public void plainPathsCodeAndRemoteImagesAreNotLocalAttachments(){String text="media/plain.png\n\n`![code](media/inline.png)`\n\n```md\n![code](media/fenced.png)\n```\n\n![remote](https://example.test/media/remote.png)\n\n\\![escaped](media/escaped.png)";assertTrue(ArchiveCodec.references(text,"markdown").isEmpty());assertTrue(ArchiveCodec.references("<p>media/plain.png</p><code>media/code.png</code><img src=\"https://example.test/media/remote.png\">","rich").isEmpty());}
 @Test public void referenceImagesAndAngleDestinationsAreRealAttachments(){assertEquals(new java.util.HashSet<>(java.util.Arrays.asList("a.png","b.jpg")),ArchiveCodec.references("![图](<media/a.png> \"标题\")\n\n![引用][pic]\n\n[pic]: media/b.jpg","markdown"));}
}
